     1→<!DOCTYPE html>
     2→<html lang="en">
     3→<head>
     4→  <meta charset="UTF-8">
     5→  <meta name="viewport" content="width=device-width, initial-scale=1.0">
     6→  <title>CPU Visualizer - Integration Tests</title>
     7→
     8→  <!-- Load design system and visualization CSS -->
     9→  <link rel="stylesheet" href="../docs/assets/css/design-system.css">
    10→  <link rel="stylesheet" href="src/visualization/visualization.css">
    11→
    12→  <style>
    13→    * {
    14→      margin: 0;
    15→      padding: 0;
    16→      box-sizing: border-box;
    17→    }
    18→
    19→    body {
    20→      font-family: 'Monaco', 'Courier New', monospace;
    21→      background: #f5f5f5;
    22→      padding: 20px;
    23→    }
    24→
    25→    .page-container {
    26→      max-width: 1400px;
    27→      margin: 0 auto;
    28→    }
    29→
    30→    .section {
    31→      background: white;
    32→      padding: 30px;
    33→      margin-bottom: 20px;
    34→      border-radius: 8px;
    35→      box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    36→    }
    37→
    38→    h1 {
    39→      font-size: 24px;
    40→      margin-bottom: 10px;
    41→      color: #2c3e50;
    42→    }
    43→
    44→    h2 {
    45→      font-size: 20px;
    46→      margin-bottom: 15px;
    47→      color: #2c3e50;
    48→    }
    49→
    50→    .subtitle {
    51→      color: #6c757d;
    52→      margin-bottom: 20px;
    53→    }
    54→
    55→    /* Live visualization controls */
    56→    .controls {
    57→      display: flex;
    58→      gap: 10px;
    59→      margin-bottom: 20px;
    60→      flex-wrap: wrap;
    61→      align-items: center;
    62→    }
    63→
    64→    .controls select,
    65→    .controls button {
    66→      padding: 8px 16px;
    67→      font-size: 14px;
    68→      border: 1px solid #ddd;
    69→      border-radius: 4px;
    70→      background: white;
    71→      cursor: pointer;
    72→    }
    73→
    74→    .controls button:hover {
    75→      background: #f0f0f0;
    76→    }
    77→
    78→    .controls button:disabled {
    79→      opacity: 0.5;
    80→      cursor: not-allowed;
    81→    }
    82→
    83→    .status {
    84→      font-size: 14px;
    85→      color: #6c757d;
    86→      padding: 8px;
    87→    }
    88→
    89→    /* Test results styles */
    90→    .summary {
    91→      font-size: 18px;
    92→      padding: 15px;
    93→      margin: 20px 0;
    94→      border-radius: 4px;
    95→      font-weight: bold;
    96→    }
    97→
    98→    .summary.success {
    99→      background: #d4edda;
   100→      color: #155724;
   101→      border: 1px solid #c3e6cb;
   102→    }
   103→
   104→    .summary.failure {
   105→      background: #f8d7da;
   106→      color: #721c24;
   107→      border: 1px solid #f5c6cb;
   108→    }
   109→
   110→    .test-section {
   111→      margin-bottom: 30px;
   112→    }
   113→
   114→    .test-section h3 {
   115→      font-size: 18px;
   116→      color: #495057;
   117→      margin-bottom: 10px;
   118→      padding-bottom: 5px;
   119→      border-bottom: 2px solid #dee2e6;
   120→    }
   121→
   122→    .test-item {
   123→      padding: 8px 12px;
   124→      margin: 4px 0;
   125→      border-radius: 4px;
   126→      font-size: 14px;
   127→    }
   128→
   129→    .test-item.pass {
   130→      background: #d4edda;
   131→      color: #155724;
   132→    }
   133→
   134→    .test-item.fail {
   135→      background: #f8d7da;
   136→      color: #721c24;
   137→    }
   138→
   139→    .test-item .label {
   140→      font-weight: bold;
   141→      margin-right: 8px;
   142→    }
   143→
   144→    .error-details {
   145→      margin-top: 4px;
   146→      padding: 8px;
   147→      background: #fff;
   148→      border-left: 3px solid #dc3545;
   149→      font-size: 12px;
   150→      color: #6c757d;
   151→    }
   152→
   153→    .loading {
   154→      text-align: center;
   155→      padding: 40px;
   156→      color: #6c757d;
   157→      font-size: 16px;
   158→    }
   159→
   160→    /* Visualization container styling */
   161→    #viz-container {
   162→      margin-top: 20px;
   163→      min-height: 400px;
   164→    }
   165→  </style>
   166→</head>
   167→<body>
   168→  <div class="page-container">
   169→    <!-- Live Visualization Section -->
   170→    <section class="section">
   171→      <h1>CPU Visualizer - Live Demo</h1>
   172→      <p class="subtitle">Interactive visualization of CPU pipeline with step controls</p>
   173→
   174→      <div class="controls">
   175→        <label for="program-select">Program:</label>
   176→        <select id="program-select">
   177→          <option value="basic">Basic Instructions</option>
   178→          <option value="fibonacci">Fibonacci</option>
   179→        </select>
   180→
   181→        <button id="btn-step-back">◀ Step Back</button>
   182→        <button id="btn-step-forward">Step Forward ▶</button>
   183→        <button id="btn-reset">↺ Reset</button>
   184→
   185→        <span class="status" id="status">Frame 0 of 0</span>
   186→      </div>
   187→
   188→      <div id="viz-container"></div>
   189→    </section>
   190→
   191→    <!-- Automated Tests Section -->
   192→    <section class="section">
   193→      <h1>Automated Tests</h1>
   194→      <p class="subtitle">Comprehensive tests for PipelineView, RegisterView, ExecutionView, and CPUVisualizer integration</p>
   195→
   196→      <div id="summary" class="loading">Running tests...</div>
   197→      <div id="results"></div>
   198→    </section>
   199→  </div>
   200→
   201→  <!-- Load Phase 9 modules in dependency order -->
   202→  <script src="src/core/cpu-state.js"></script>
   203→  <script src="src/core/instruction-set.js"></script>
   204→  <script src="src/animation/timing-controller.js"></script>
   205→  <script src="src/animation/animation-engine.js"></script>
   206→  <script src="src/core/sequence-generator.js"></script>
   207→  <script src="src/programs/basic-instructions.js"></script>
   208→  <script src="src/programs/fibonacci.js"></script>
   209→
   210→  <!-- Load Phase 10 visualization modules -->
   211→  <script src="src/visualization/pipeline-view.js"></script>
   212→  <script src="src/visualization/register-view.js"></script>
   213→  <script src="src/visualization/execution-view.js"></script>
   214→  <script src="src/visualization/cpu-visualizer.js"></script>
   215→
   216→  <!-- Test suite and live demo -->
   217→  <script>
   218→    (function() {
   219→      'use strict';
   220→
   221→      // Test framework
   222→      let passCount = 0;
   223→      let failCount = 0;
   224→      const results = [];
   225→
   226→      function test(name, fn) {
   227→        try {
   228→          fn();
   229→          passCount++;
   230→          results.push({ name, pass: true });
   231→        } catch (e) {
   232→          failCount++;
   233→          results.push({ name, pass: false, error: e.message });
   234→        }
   235→      }
   236→
   237→      function assert(condition, message) {
   238→        if (!condition) {
   239→          throw new Error(message || 'Assertion failed');
   240→        }
   241→      }
   242→
   243→      function assertEquals(actual, expected, message) {
   244→        if (actual !== expected) {
   245→          throw new Error(message || `Expected ${expected}, got ${actual}`);
   246→        }
   247→      }
   248→
   249→      function assertGreaterThan(actual, threshold, message) {
   250→        if (actual <= threshold) {
   251→          throw new Error(message || `Expected ${actual} > ${threshold}`);
   252→        }
   253→      }
   254→
   255→      // Live demo state
   256→      let animationEngine = null;
   257→      let visualizer = null;
   258→      let currentProgram = 'basic';
   259→
   260→      // Initialize live demo when DOM is ready
   261→      document.addEventListener('DOMContentLoaded', function() {
   262→        initializeLiveDemo();
   263→        runAllTests();
   264→        displayResults();
   265→      });
   266→
   267→      function initializeLiveDemo() {
   268→        const vizContainer = document.getElementById('viz-container');
   269→        const programSelect = document.getElementById('program-select');
   270→        const btnStepBack = document.getElementById('btn-step-back');
   271→        const btnStepForward = document.getElementById('btn-step-forward');
   272→        const btnReset = document.getElementById('btn-reset');
   273→        const statusEl = document.getElementById('status');
   274→
   275→        // Create visualizer
   276→        visualizer = new CPUVisualizer(vizContainer);
   277→
   278→        // Create animation engine
   279→        animationEngine = new AnimationEngine();
   280→
   281→        // Listen to frame changes to update status
   282→        window.addEventListener('cpu:framechange', function(e) {
   283→          const index = e.detail.index;
   284→          const total = animationEngine.getTotalFrames();
   285→          statusEl.textContent = `Frame ${index} of ${total - 1}`;
   286→        });
   287→
   288→        // Load initial program
   289→        loadProgram(currentProgram);
   290→
   291→        // Wire up controls
   292→        programSelect.addEventListener('change', function() {
   293→          currentProgram = this.value;
   294→          loadProgram(currentProgram);
   295→        });
   296→
   297→        btnStepBack.addEventListener('click', function() {
   298→          animationEngine.stepBackward();
   299→        });
   300→
   301→        btnStepForward.addEventListener('click', function() {
   302→          animationEngine.stepForward();
   303→        });
   304→
   305→        btnReset.addEventListener('click', function() {
   306→          animationEngine.reset();
   307→        });
   308→      }
   309→
   310→      function loadProgram(programName) {
   311→        const program = programName === 'basic' ? BASIC_PROGRAM : FIBONACCI_PROGRAM;
   312→        const result = SequenceGenerator.generateSequence(program.instructions);
   313→        animationEngine.loadFrames(result.frames);
   314→
   315→        const statusEl = document.getElementById('status');
   316→        statusEl.textContent = `Frame 0 of ${result.frames.length - 1}`;
   317→      }
   318→
   319→      function runAllTests() {
   320→        // ============================================
   321→        // PIPELINEVIEW TESTS
   322→        // ============================================
   323→
   324→        test('PipelineView creates 5 stage cards', function() {
   325→          const container = document.createElement('div');
   326→          const view = new PipelineView(container);
   327→
   328→          const stages = container.querySelectorAll('[data-stage]');
   329→          assertEquals(stages.length, 5, 'Should have 5 stage cards');
   330→
   331→          const stageNames = Array.from(stages).map(s => s.dataset.stage);
   332→          assert(stageNames.includes('IF'), 'Should have IF stage');
   333→          assert(stageNames.includes('ID'), 'Should have ID stage');
   334→          assert(stageNames.includes('EX'), 'Should have EX stage');
   335→          assert(stageNames.includes('MEM'), 'Should have MEM stage');
   336→          assert(stageNames.includes('WB'), 'Should have WB stage');
   337→        });
   338→
   339→        test('PipelineView shows NOP for inactive stages', function() {
   340→          const container = document.createElement('div');
   341→          const view = new PipelineView(container);
   342→          const state = CPUState.createInitial();
   343→
   344→          view.render(state);
   345→
   346→          const instructionTexts = container.querySelectorAll('[data-stage-instruction]');
   347→          instructionTexts.forEach(el => {
   348→            assertEquals(el.textContent, 'NOP', 'Inactive stage should show NOP');
   349→          });
   350→        });
   351→
   352→        test('PipelineView shows instruction for active IF stage', function() {
   353→          const container = document.createElement('div');
   354→          const view = new PipelineView(container);
   355→          const state = CPUState.createInitial();
   356→
   357→          state.pipeline.IF.active = true;
   358→          state.pipeline.IF.instruction = InstructionSet.createInstruction('ADDI', {
   359→            rs: 0, rt: 8, immediate: 42
   360→          });
   361→
   362→          view.render(state);
   363→
   364→          const ifCard = container.querySelector('[data-stage="IF"]');
   365→          const instructionEl = ifCard.querySelector('[data-stage-instruction]');
   366→          assert(instructionEl.textContent.includes('ADDI'), 'Should show ADDI instruction');
   367→          assert(ifCard.classList.contains('active'), 'IF card should have active class');
   368→        });
   369→
   370→        test('PipelineView shows instruction for active EX stage', function() {
   371→          const container = document.createElement('div');
   372→          const view = new PipelineView(container);
   373→          const state = CPUState.createInitial();
   374→
   375→          state.pipeline.IF.instruction = InstructionSet.createInstruction('ADD', {
   376→            rs: 1, rt: 2, rd: 3
   377→          });
   378→          state.pipeline.EX.active = true;
   379→
   380→          view.render(state);
   381→
   382→          const exCard = container.querySelector('[data-stage="EX"]');
   383→          const instructionEl = exCard.querySelector('[data-stage-instruction]');
   384→          assert(instructionEl.textContent.includes('ADD'), 'Should show ADD instruction');
   385→          assert(exCard.classList.contains('active'), 'EX card should have active class');
   386→        });
   387→
   388→        test('Stage cards have correct data-stage attributes', function() {
   389→          const container = document.createElement('div');
   390→          const view = new PipelineView(container);
   391→
   392→          assert(container.querySelector('[data-stage="IF"]'), 'IF stage exists');
   393→          assert(container.querySelector('[data-stage="ID"]'), 'ID stage exists');
   394→          assert(container.querySelector('[data-stage="EX"]'), 'EX stage exists');
   395→          assert(container.querySelector('[data-stage="MEM"]'), 'MEM stage exists');
   396→          assert(container.querySelector('[data-stage="WB"]'), 'WB stage exists');
   397→        });
   398→
   399→        // ============================================
   400→        // REGISTERVIEW TESTS
   401→        // ============================================
   402→
   403→        test('RegisterView creates 32 register cells', function() {
   404→          const container = document.createElement('div');
   405→          const view = new RegisterView(container);
   406→
   407→          const cells = container.querySelectorAll('[data-register]');
   408→          assertEquals(cells.length, 32, 'Should have 32 register cells');
   409→
   410→          // Check first and last
   411→          assert(container.querySelector('[data-register="0"]'), 'Register $0 exists');
   412→          assert(container.querySelector('[data-register="31"]'), 'Register $31 exists');
   413→        });
   414→
   415→        test('RegisterView shows hex values', function() {
   416→          const container = document.createElement('div');
   417→          const view = new RegisterView(container);
   418→          const state = CPUState.createInitial();
   419→
   420→          view.render(state);
   421→
   422→          const values = container.querySelectorAll('.register-value');
   423→          values.forEach(el => {
   424→            assert(el.textContent.startsWith('0x'), 'Values should be hex format');
   425→          });
   426→        });
   427→
   428→        test('RegisterView highlights changed registers', function() {
   429→          const container = document.createElement('div');
   430→          const view = new RegisterView(container);
   431→          const state = CPUState.createInitial();
   432→
   433→          // First render to initialize
   434→          view.render(state);
   435→
   436→          // Second render with changes
   437→          state.setRegister(5, 0x12345678);
   438→          state.setRegister(7, 0xABCDEF00);
   439→          view.render(state);
   440→
   441→          const cell5 = container.querySelector('[data-register="5"]');
   442→          const cell7 = container.querySelector('[data-register="7"]');
   443→
   444→          assert(cell5.classList.contains('changed'), 'Register 5 should be highlighted');
   445→          assert(cell7.classList.contains('changed'), 'Register 7 should be highlighted');
   446→
   447→          const value5 = cell5.querySelector('.register-value');
   448→          assertEquals(value5.textContent, '0x12345678', 'Register 5 value should update');
   449→        });
   450→
   451→        test('RegisterView removes highlight on next render', function() {
   452→          const container = document.createElement('div');
   453→          const view = new RegisterView(container);
   454→          const state = CPUState.createInitial();
   455→
   456→          // First render
   457→          view.render(state);
   458→
   459→          // Second render with changes
   460→          state.setRegister(5, 100);
   461→          view.render(state);
   462→
   463→          assert(container.querySelector('[data-register="5"]').classList.contains('changed'),
   464→            'Should have highlight after change');
   465→
   466→          // Third render with no changes
   467→          const state2 = state.clone();
   468→          state2.changedRegisters.clear();
   469→          view.render(state2);
   470→
   471→          assert(!container.querySelector('[data-register="5"]').classList.contains('changed'),
   472→            'Highlight should be removed');
   473→        });
   474→
   475→        test('Register $0 cell has reduced opacity style', function() {
   476→          const container = document.createElement('div');
   477→          const view = new RegisterView(container);
   478→
   479→          const cell0 = container.querySelector('[data-register="0"]');
   480→          assert(cell0, 'Register $0 cell exists (CSS applies opacity)');
   481→        });
   482→
   483→        // ============================================
   484→        // EXECUTIONVIEW TESTS
   485→        // ============================================
   486→
   487→        test('ExecutionView shows cycle count', function() {
   488→          const container = document.createElement('div');
   489→          const view = new ExecutionView(container);
   490→          const state = CPUState.createInitial();
   491→
   492→          state.cycleCount = 5;
   493→          view.render(state);
   494→
   495→          const cycleEl = container.querySelector('[data-cycle-count]');
   496→          assertEquals(cycleEl.textContent, '5', 'Cycle count should be 5');
   497→        });
   498→
   499→        test('ExecutionView shows instruction count', function() {
   500→          const container = document.createElement('div');
   501→          const view = new ExecutionView(container);
   502→          const state = CPUState.createInitial();
   503→
   504→          state.instructionCount = 2;
   505→          view.render(state);
   506→
   507→          const instructionEl = container.querySelector('[data-instruction-count]');
   508→          assertEquals(instructionEl.textContent, '2', 'Instruction count should be 2');
   509→        });
   510→
   511→        test('ExecutionView container has aria-live attribute', function() {
   512→          const container = document.createElement('div');
   513→          container.setAttribute('aria-live', 'polite');
   514→          const view = new ExecutionView(container);
   515→
   516→          assertEquals(container.getAttribute('aria-live'), 'polite',
   517→            'Container should have aria-live="polite"');
   518→        });
   519→
   520→        // ============================================
   521→        // CPUVISUALIZER INTEGRATION TESTS
   522→        // ============================================
   523→
   524→        test('CPUVisualizer creates DOM structure', function() {
   525→          const container = document.createElement('div');
   526→          const visualizer = new CPUVisualizer(container);
   527→
   528→          assert(container.querySelector('.pipeline-section'), 'Pipeline section exists');
   529→          assert(container.querySelector('.data-section'), 'Data section exists');
   530→          assert(container.querySelector('.registers-section'), 'Registers section exists');
   531→          assert(container.querySelector('.execution-section'), 'Execution section exists');
   532→          assert(container.querySelector('[data-pipeline-view]'), 'Pipeline view container exists');
   533→          assert(container.querySelector('[data-register-view]'), 'Register view container exists');
   534→          assert(container.querySelector('[data-execution-view]'), 'Execution view container exists');
   535→        });
   536→
   537→        test('CPUVisualizer responds to cpu:framechange event', function() {
   538→          const container = document.createElement('div');
   539→          const visualizer = new CPUVisualizer(container);
   540→          const state = CPUState.createInitial();
   541→
   542→          state.cycleCount = 10;
   543→          state.instructionCount = 3;
   544→          state.pipeline.IF.active = true;
   545→          state.pipeline.IF.instruction = InstructionSet.createInstruction('ADDI', {
   546→            rs: 0, rt: 8, immediate: 42
   547→          });
   548→
   549→          // Dispatch synthetic event
   550→          const event = new CustomEvent('cpu:framechange', {
   551→            detail: { state: state, index: 1, total: 10 }
   552→          });
   553→          window.dispatchEvent(event);
   554→
   555→          // Check if views were updated
   556→          const cycleEl = container.querySelector('[data-cycle-count]');
   557→          assertEquals(cycleEl.textContent, '10', 'Cycle count should update');
   558→
   559→          const ifCard = container.querySelector('[data-stage="IF"]');
   560→          assert(ifCard.classList.contains('active'), 'IF stage should be active');
   561→        });
   562→
   563→        test('Full program playback updates visualization', function() {
   564→          const container = document.createElement('div');
   565→          const visualizer = new CPUVisualizer(container);
   566→          const engine = new AnimationEngine();
   567→
   568→          const result = SequenceGenerator.generateSequence(BASIC_PROGRAM.instructions);
   569→          engine.loadFrames(result.frames);
   570→
   571→          // Step forward 6 times (through first instruction's WB stage)
   572→          for (let i = 0; i < 6; i++) {
   573→            engine.stepForward();
   574→          }
   575→
   576→          // Check that visualization shows updated state
   577→          const cycleEl = container.querySelector('[data-cycle-count]');
   578→          assertGreaterThan(parseInt(cycleEl.textContent), 0, 'Cycle count should be > 0');
   579→
   580→          // Check that at least one stage is active
   581→          const activeStages = container.querySelectorAll('.pipeline-stage.active');
   582→          assertGreaterThan(activeStages.length, 0, 'At least one stage should be active');
   583→        });
   584→
   585→        test('Step backward restores previous state', function() {
   586→          const container = document.createElement('div');
   587→          const visualizer = new CPUVisualizer(container);
   588→          const engine = new AnimationEngine();
   589→
   590→          const result = SequenceGenerator.generateSequence(BASIC_PROGRAM.instructions);
   591→          engine.loadFrames(result.frames);
   592→
   593→          // Step forward then back
   594→          engine.stepForward();
   595→          engine.stepForward();
   596→          const forwardCycles = parseInt(container.querySelector('[data-cycle-count]').textContent);
   597→
   598→          engine.stepBackward();
   599→          const backwardCycles = parseInt(container.querySelector('[data-cycle-count]').textContent);
   600→
   601→          assert(backwardCycles < forwardCycles, 'Cycle count should decrease after step back');
   602→        });
   603→
   604→        test('CPUVisualizer.destroy() removes event listener', function() {
   605→          const container = document.createElement('div');
   606→          const visualizer = new CPUVisualizer(container);
   607→
   608→          visualizer.destroy();
   609→
   610→          // Dispatch event after destroy
   611→          const state = CPUState.createInitial();
   612→          state.cycleCount = 99;
   613→          const event = new CustomEvent('cpu:framechange', {
   614→            detail: { state: state }
   615→          });
   616→
   617→          // This should not throw an error
   618→          window.dispatchEvent(event);
   619→
   620→          // Container should be empty
   621→          assertEquals(container.innerHTML, '', 'Container should be cleared');
   622→        });
   623→      }
   624→
   625→      function displayResults() {
   626→        const summaryEl = document.getElementById('summary');
   627→        const resultsEl = document.getElementById('results');
   628→
   629→        // Summary
   630→        const total = passCount + failCount;
   631→        if (failCount === 0) {
   632→          summaryEl.className = 'summary success';
   633→          summaryEl.textContent = `✓ All ${total} tests passed!`;
   634→        } else {
   635→          summaryEl.className = 'summary failure';
   636→          summaryEl.textContent = `✗ ${failCount} of ${total} tests failed`;
   637→        }
   638→
   639→        // Group results by component
   640→        const sections = {
   641→          'PipelineView': [],
   642→          'RegisterView': [],
   643→          'ExecutionView': [],
   644→          'CPUVisualizer': []
   645→        };
   646→
   647→        results.forEach(result => {
   648→          if (result.name.includes('PipelineView')) {
   649→            sections['PipelineView'].push(result);
   650→          } else if (result.name.includes('RegisterView')) {
   651→            sections['RegisterView'].push(result);
   652→          } else if (result.name.includes('ExecutionView')) {
   653→            sections['ExecutionView'].push(result);
   654→          } else if (result.name.includes('CPUVisualizer')) {
   655→            sections['CPUVisualizer'].push(result);
   656→          }
   657→        });
   658→
   659→        // Render sections
   660→        Object.keys(sections).forEach(sectionName => {
   661→          if (sections[sectionName].length === 0) return;
   662→
   663→          const sectionDiv = document.createElement('div');
   664→          sectionDiv.className = 'test-section';
   665→
   666→          const title = document.createElement('h3');
   667→          title.textContent = sectionName + ' Tests';
   668→          sectionDiv.appendChild(title);
   669→
   670→          sections[sectionName].forEach(result => {
   671→            const item = document.createElement('div');
   672→            item.className = 'test-item ' + (result.pass ? 'pass' : 'fail');
   673→
   674→            const label = document.createElement('span');
   675→            label.className = 'label';
   676→            label.textContent = result.pass ? 'PASS' : 'FAIL';
   677→            item.appendChild(label);
   678→
   679→            const name = document.createTextNode(result.name);
   680→            item.appendChild(name);
   681→
   682→            if (!result.pass && result.error) {
   683→              const error = document.createElement('div');
   684→              error.className = 'error-details';
   685→              error.textContent = result.error;
   686→              item.appendChild(error);
   687→            }
   688→
   689→            sectionDiv.appendChild(item);
   690→          });
   691→
   692→          resultsEl.appendChild(sectionDiv);
   693→        });
   694→      }
   695→    })();
