    45→      // Bind and register event listener for AnimationEngine events
    46→      this._handleFrameChange = this._handleFrameChange.bind(this);
    47→      window.addEventListener('cpu:framechange', this._handleFrameChange);
    48→    }
    49→
    50→    /**
    51→     * Creates the visualization DOM structure inside the container
    52→     * @private
    53→     */
    54→    _createDOM() {
    55→      this.container.innerHTML = `
    56→        <section class="pipeline-section">
    57→          <h2>Pipeline Stages</h2>
    58→          <div class="pipeline-stages" data-pipeline-view></div>
    59→        </section>
    60→        <aside class="data-section">
    61→          <section class="registers-section">
    62→            <h2>Registers</h2>
