     1→/**
     2→ * PipelineView - 5-stage pipeline visualization component
     3→ *
     4→ * Renders IF, ID, EX, MEM, WB pipeline stages with color-coded borders.
     5→ * Displays instruction mnemonic + formatted operands for active stages.
     6→ * Shows 'NOP' for inactive stages.
     7→ *
     8→ * Usage:
     9→ *   const view = new PipelineView(containerElement);
    10→ *   view.render(cpuState);
    11→ */
    12→(function() {
    13→  'use strict';
    14→
    15→  class PipelineView {
    16→    /**
    17→     * Creates a PipelineView instance
    18→     * @param {HTMLElement} container - DOM element to render pipeline stages into
    19→     */
    20→    constructor(container) {
    21→      this.container = container;
    22→      this.stageElements = new Map();  // Fast stage lookup
    23→      this.initializeStages();
    24→    }
    25→
    26→    /**
    27→     * Creates the 5 pipeline stage cards in the DOM
    28→     * Uses DocumentFragment for efficient batch insertion
    29→     */
    30→    initializeStages() {
    31→      const stageNames = ['IF', 'ID', 'EX', 'MEM', 'WB'];
    32→      const fullNames = {
    33→        IF: 'Instruction Fetch',
    34→        ID: 'Instruction Decode',
    35→        EX: 'Execute',
    36→        MEM: 'Memory Access',
    37→        WB: 'Write Back'
    38→      };
    39→
    40→      const fragment = document.createDocumentFragment();
    41→
    42→      stageNames.forEach(stageName => {
    43→        const stageCard = document.createElement('div');
    44→        stageCard.className = 'pipeline-stage';
    45→        stageCard.dataset.stage = stageName;
    46→
    47→        stageCard.innerHTML = `
    48→          <div class="stage-header">
    49→            <span class="stage-label">${stageName}</span>
    50→            <span class="stage-name">${fullNames[stageName]}</span>
    51→          </div>
    52→          <div class="stage-content">
    53→            <code class="instruction-text" data-stage-instruction>NOP</code>
    54→          </div>
    55→        `;
    56→
    57→        this.stageElements.set(stageName, stageCard);
    58→        fragment.appendChild(stageCard);
    59→      });
    60→
    61→      // Single DOM insertion for all stages
    62→      this.container.appendChild(fragment);
    63→    }
    64→
    65→    /**
    66→     * Renders the current pipeline state
    67→     * @param {CPUState} state - Current CPU state with pipeline data
    68→     */
    69→    render(state) {
    70→      const stageNames = ['IF', 'ID', 'EX', 'MEM', 'WB'];
    71→
    72→      stageNames.forEach(stageName => {
    73→        const stageData = state.pipeline[stageName];
    74→        const stageCard = this.stageElements.get(stageName);
    75→        const instructionEl = stageCard.querySelector('[data-stage-instruction]');
    76→
    77→        if (stageData.active) {
    78→          // Get instruction from IF stage (in non-pipelined mode, the instruction flows through all stages)
    79→          // IF and ID stages store the instruction directly
    80→          const instruction = state.pipeline.IF.instruction;
    81→
    82→          if (instruction) {
    83→            const displayText = `${instruction.mnemonic} ${this.formatOperands(instruction)}`.trim();
    84→            instructionEl.textContent = displayText;
    85→          } else {
    86→            instructionEl.textContent = 'NOP';
    87→          }
    88→
    89→          stageCard.classList.add('active');
    90→        } else {
    91→          instructionEl.textContent = 'NOP';
    92→          stageCard.classList.remove('active');
    93→        }
    94→      });
    95→    }
    96→
    97→    /**
    98→     * Formats instruction operands for assembly-style display
    99→     * @param {object} instruction - Instruction object with mnemonic, type, and operand fields
   100→     * @returns {string} Formatted operand string
   101→     * @private
   102→     */
   103→    formatOperands(instruction) {
   104→      if (!instruction || instruction.mnemonic === 'NOP') {
   105→        return '';
   106→      }
   107→
   108→      const { type, rs, rt, rd, immediate } = instruction;
   109→
   110→      switch (type) {
   111→        case 'R':
   112→          // R-type: ADD $rd, $rs, $rt
   113→          return `$${rd}, $${rs}, $${rt}`;
   114→
   115→        case 'I':
   116→          if (instruction.mnemonic === 'ADDI') {
   117→            // ADDI $rt, $rs, imm
   118→            return `$${rt}, $${rs}, ${immediate}`;
   119→          } else if (instruction.mnemonic === 'LW') {
   120→            // LW $rt, imm($rs)
   121→            return `$${rt}, ${immediate}($${rs})`;
   122→          }
   123→          break;
   124→
   125→        case 'S':
   126→          // SW $rt, imm($rs)
   127→          return `$${rt}, ${immediate}($${rs})`;
   128→
   129→        case 'B':
   130→          // BEQ $rs, $rt, offset
   131→          return `$${rs}, $${rt}, ${immediate}`;
   132→
   133→        case 'J':
   134→          // J target
   135→          return `${immediate}`;
   136→
   137→        case 'NOP':
   138→          return '';
   139→
   140→        default:
   141→          return '';
   142→      }
   143→
   144→      return '';
   145→    }
   146→  }
   147→
   148→  // Export to global scope (vanilla JS pattern)
   149→  if (typeof window !== 'undefined') {
   150→    window.PipelineView = PipelineView;
   151→  } else if (typeof global !== 'undefined') {
   152→    global.PipelineView = PipelineView;
   153→  }
   154→})();
