   336→### Efficient Register Update (Only Changed)
   337→```javascript
   338→// Source: DOM manipulation best practices 2026
   339→class RegisterView {
   340→  constructor(containerElement) {
   341→    this.container = containerElement;
   342→    this.cells = new Map(); // Cache DOM references
   343→    this.buildGrid();
   344→  }
   345→
   346→  buildGrid() {
   347→    // Create structure once
   348→    const fragment = document.createDocumentFragment();
   349→
   350→    for (let i = 0; i < 32; i++) {
   351→      const cell = document.createElement('div');
   352→      cell.className = 'register-cell';
   353→      cell.dataset.register = i;
   354→      cell.innerHTML = `
   355→        <div class="register-name">$${i}</div>
   356→        <div class="register-value" data-value>0x00000000</div>
   357→      `;
   358→
   359→      this.cells.set(i, {
   360→        element: cell,
   361→        valueEl: cell.querySelector('[data-value]')
   362→      });
   363→
   364→      fragment.appendChild(cell);
   365→    }
   366→
   367→    this.container.appendChild(fragment);
   368→  }
   369→
   370→  update(registers, changedRegisters) {
   371→    // Only update changed registers
   372→    changedRegisters.forEach(regNum => {
   373→      const { element, valueEl } = this.cells.get(regNum);
   374→
   375→      // Update value
   376→      valueEl.textContent = this.formatHex(registers[regNum]);
   377→
   378→      // Add highlight class (CSS handles animation)
   379→      element.classList.add('changed');
   380→
   381→      // Remove highlight after animation
   382→      setTimeout(() => {
   383→        element.classList.remove('changed');
   384→      }, 500);
   385→    });
   386→  }
   387→
   388→  formatHex(value) {
   389→    return '0x' + value.toString(16).toUpperCase().padStart(8, '0');
   390→  }
