   394→### Pipeline Stage Visualization
   395→```javascript
   396→// Source: Educational CPU visualization patterns
   397→class PipelineView {
   398→  constructor(containerElement) {
   399→    this.container = containerElement;
   400→    this.stages = ['IF', 'ID', 'EX', 'MEM', 'WB'];
   401→    this.stageElements = new Map();
   402→    this.buildPipeline();
   403→  }
   404→
   405→  buildPipeline() {
   406→    const fragment = document.createDocumentFragment();
   407→
   408→    this.stages.forEach(stageName => {
   409→      const stageCard = document.createElement('div');
   410→      stageCard.className = 'pipeline-stage';
   411→      stageCard.dataset.stage = stageName;
   412→      stageCard.innerHTML = `
   413→        <div class="stage-header">${stageName}</div>
   414→        <div class="stage-content" data-content>
   415→          <div class="stage-instruction">-</div>
   416→          <div class="stage-details"></div>
   417→        </div>
   418→      `;
   419→
   420→      this.stageElements.set(stageName, {
   421→        element: stageCard,
   422→        contentEl: stageCard.querySelector('[data-content]')
   423→      });
   424→
   425→      fragment.appendChild(stageCard);
   426→    });
   427→
   428→    this.container.appendChild(fragment);
   429→  }
   430→
   431→  update(pipeline, activeStages) {
   432→    this.stages.forEach(stageName => {
   433→      const { element, contentEl } = this.stageElements.get(stageName);
   434→      const stageData = pipeline[stageName];
   435→
   436→      // Toggle active class
   437→      if (activeStages.has(stageName)) {
   438→        element.classList.add('active');
   439→      } else {
   440→        element.classList.remove('active');
   441→      }
   442→
   443→      // Update instruction display
   444→      const instruction = stageData.instruction;
   445→      const instrEl = contentEl.querySelector('.stage-instruction');
   446→
   447→      if (instruction && stageData.active) {
   448→        instrEl.textContent = this.formatInstruction(instruction);
   449→      } else {
   450→        instrEl.textContent = '-';
   451→      }
   452→    });
   453→  }
   454→
   455→  formatInstruction(instruction) {
   456→    // Format: "ADD $10, $8, $9"
   457→    const { mnemonic, rs, rt, rd, immediate } = instruction;
   458→
   459→    if (mnemonic === 'ADDI' || mnemonic === 'LW' || mnemonic === 'SW') {
   460→      return `${mnemonic} $${rt}, $${rs}, ${immediate}`;
   461→    } else if (mnemonic === 'BEQ') {
   462→      return `${mnemonic} $${rs}, $${rt}, ${immediate}`;
   463→    } else if (mnemonic === 'J') {
   464→      return `${mnemonic} ${immediate}`;
   465→    } else {
   466→      return `${mnemonic} $${rd}, $${rs}, $${rt}`;
   467→    }
   468→  }
   469→}
   470→```
